/// <summary>
/// The <c>AVAWHSProcessGuidePromptCoilCalculatorDataPageBuilder</c> builds a page for ask the calculator data
/// and then confirm.
/// </summary>
[
    ProcessGuidePageBuilderName(classStr(AVAWHSProcessGuidePromptCoilCalculatorDataPageBuilder))
]
class AVAWHSProcessGuidePromptCoilCalculatorDataPageBuilder extends ProcessGuidePageBuilder
{
}

Method.Source:
protected final void addDataControls(ProcessGuidePage _page)
{
    WhsrfPassthrough            pass;

    boolean                     show_WMSLocationId;
    boolean                     show_ItemId;
    boolean                     show_CoilWidth;
    boolean                     show_CoilOutsideDiameter;
    boolean                     show_CoilInsideDiameter;

    WMSLocationId               locationId;
    ItemId                      itemId;
    AVACoilWidth                coilWidth;
    AVACoilInsideDiameter       coilInsideWidth;
    AVACoilOutsideDiameter      coilOutsideWidth;

    WMSLocation                 location;

    pass                        = controller.parmSessionState().parmPass();

    show_WMSLocationId          = true;
    show_ItemId                 = pass.lookupStr(ProcessGuideDataTypeNames::WMSLocationId) != '' ? true : false;
    show_CoilWidth              = pass.lookupStr(ProcessGuideDataTypeNames::ItemId)  != '' ? true : false;
    show_CoilOutsideDiameter    = pass.lookupReal(ProcessGuideDataTypeNames::AVACoilWidth)  != 0.0 ? true : false;
    show_CoilInsideDiameter     = pass.lookupReal(ProcessGuideDataTypeNames::AVACoilOutsideDiameter)  != 0.0 ? true : false;

    if (show_WMSLocationId)
    {
        _page.addTextBox(ProcessGuideDataTypeNames::LocOrLP, "@WAX1146", extendedTypeNum(WHSLicensePlateId), true, pass.lookupStr(ProcessGuideDataTypeNames::WMSLocationId));
    }         

    location  = WMSLocation::find(pass.lookupStr(ProcessGuideDataTypeNames::WMSLocationId),
                                  pass.lookupStr(ProcessGuideDataTypeNames::InventLocationId));

    if (location
     && location.whsLocationIsLPControlled())
    {
        _page.addTextBox(ProcessGuideDataTypeNames::LicensePlateId, "@WAX1198", extendedTypeNum(WHSLicensePlateId), true, pass.lookupStr(ProcessGuideDataTypeNames::LicensePlateId));
    }

    if (show_ItemId)
    {
        _page.addTextBox(ProcessGuideDataTypeNames::ItemId, "@SYS14428", extendedTypeNum(ItemId), true, pass.parmItemId());
    }

    if (show_CoilWidth)
    {
        _page.addTextBox(ProcessGuideDataTypeNames::AVACoilWidth,
                         "@NDX:CoilWidth",
                         extendedTypeNum(AVACoilWidth),
                         true,
                         pass.avaParmCoilWidth() ? WHSWorkExecuteDisplay::num2StrDisplay(pass.avaParmCoilWidth()) : '');
    }

    if (show_CoilOutsideDiameter)
    {
        _page.addTextBox(ProcessGuideDataTypeNames::AVACoilOutsideDiameter,
                         "@NDX:CoilOutsideDiameter",
                         extendedTypeNum(AVACoilOutsideDiameter),
                         true,
                         pass.avaParmCoilOutsideDiameter() ? WHSWorkExecuteDisplay::num2StrDisplay(pass.avaParmCoilOutsideDiameter()) : '');
    }

    if (show_CoilInsideDiameter)
    {

        _page.addTextBox(ProcessGuideDataTypeNames::AVACoilInsideDiameter,
                         "@NDX:CoilInsideDiameter",
                         extendedTypeNum(AVACoilInsideDiameter),
                         true,
                         pass.avaParmCoilInsideDiameter() ? WHSWorkExecuteDisplay::num2StrDisplay(pass.avaParmCoilInsideDiameter()) : this.avaGetDefaultInsideDiameter(pass.parmItemId()));
    }
}

protected str avaGetDefaultInsideDiameter(ItemId _itemId)
{
    AVACoilInsideDiameter           coilInsideDiameter;
    str                             returnStr;
    InventTable                     inventTable;
    InventTable_NDXTrumpf           inventTable_NDXTrumpf;
    NDXTRUMPFMaterialCharacteristic materialCharacteristic;
    AVADefaultCoilDiameterTable     defaultCoilDiameterTable;

    inventTable                 = InventTable::find(_itemId);
    inventTable_NDXTrumpf       = InventTable_NDXTrumpf::findByInventTable(inventTable.RecId);
    materialCharacteristic      = NDXTRUMPFMaterialCharacteristic::findByRecId(inventTable_NDXTrumpf.CharacteristicRefRecId);
    defaultCoilDiameterTable    = AVADefaultCoilDiameterTable::search(inventTable.ItemId, materialCharacteristic.NDX_CharacteristicID);

    if (defaultCoilDiameterTable)
    {
        coilInsideDiameter = defaultCoilDiameterTable.InsideDiameter;
    }

    if (coilInsideDiameter)
    {
        returnStr = WHSWorkExecuteDisplay::num2StrDisplay(coilInsideDiameter);
    }
    else
    {
        returnStr = '';
    }        

    return returnStr;
}
